INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65965291', 65965291, 'analyze_legacy', 'Badan Pusat Statistik', 'central', 'BADAN PUSAT STATISTIK KAB KUTAI BARAT', 'Pengadaan software pendukung perwajahan publikasi BPS Kabupaten/Kota', 'Barang', 'Pengadaan Langsung', 'Kalimantan Timur, Kutai Barat (Kab.)', 7945000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1 Paket, @Rp 7.945.000 )', '1. Pengadaan software pendukung perwajahan publikasi BPS Kabupaten/Kota ( 1 Paket, @Rp 7.945.000 );', 'Nama Paket : Pengadaan Software Pendukung Perwajahan Publikasi BPS Kabupaten/Kota Volume : 1 (Satu) Paket Harga Satuan : @Rp 7.945.000 1. Ruang Lingkup Pekerjaan Penyedia melaksanakan pengadaan software/aplikasi berlisensi resmi yang digunakan untuk mendukung kegiatan desain, tata letak (layout), dan perwajahan publikasi pada BPS Kabupaten/Kota. 2. Spesifikasi Teknis - Software merupakan aplikasi desain grafis dan/atau desktop publishing yang mendukung pembuatan tata letak publikasi statistik. - Memiliki fitur pengolahan layout, pengaturan tipografi, pengolahan gambar, serta ekspor file ke format siap cetak (PDF high resolution). - Lisensi resmi dan legal, bukan bajakan atau ilegal. - Masa berlaku lisensi minimal 1 (satu) tahun atau sesuai ketentuan lisensi yang dibeli. - Kompatibel dengan sistem operasi dan perangkat yang digunakan di lingkungan BPS Kabupaten/Kota. - Mendukung penggunaan font dan elemen grafis sesuai standar perwajahan publikasi BPS. 3. Persyaratan - Harga yang ditawarkan merupakan harga wajar dan sesuai harga pasar yang berlaku. - Harga sudah termasuk pajak dan biaya administrasi lainnya. - Penyedia bertanggung jawab atas proses instalasi, aktivasi, dan keberfungsian software. - Penyedia memberikan bukti lisensi resmi atas software yang diadakan. - Apabila terjadi kendala aktivasi atau lisensi, penyedia wajib melakukan penyelesaian tanpa biaya tambahan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2470119);
