INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65970071', 65970071, 'analyze_legacy', 'Badan Pusat Statistik', 'central', 'BADAN PUSAT STATISTIK KAB KUTAI BARAT', 'penggandaan daftar isian survei harga perdesaan', 'Barang', 'Pengadaan Langsung', 'Kalimantan Timur, Kutai Barat (Kab.)', 612000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1224 Lmbr, @Rp 500 )', '1. penggandaan daftar isian survei harga perdesaan ( 1224 Lmbr, @Rp 500 );', 'Nama Paket : Penggandaan Daftar Isian Survei Harga Perdesaan Volume : 1.224 (Seribu Dua Ratus Dua Puluh Empat) Lembar Harga Satuan : @ Rp500 1. Ruang Lingkup Pekerjaan Penyedia melaksanakan penggandaan (fotokopi/percetakan) daftar isian Survei Harga Perdesaan sesuai dengan format dan naskah yang disediakan oleh penyelenggara. 2. Spesifikasi Teknis - Penggandaan dilakukan sesuai format asli tanpa perubahan tata letak maupun isi. - Menggunakan kertas HVS ukuran A4/F4 dengan gramasi standar (70/75 gsm). - Hasil cetakan jelas, tidak buram, tidak terpotong, dan mudah dibaca. - Tinta cetak tidak luntur dan tidak tembus berlebihan ke halaman belakang. - Dokumen disusun rapi dan dikelompokkan sesuai kebutuhan. 3. Persyaratan - Harga yang ditawarkan merupakan harga wajar dan sesuai harga pasar yang berlaku. - Harga sudah termasuk pajak dan biaya pengemasan. - Penyedia bertanggung jawab atas kualitas hasil cetak dan jumlah lembar yang sesuai dengan pesanan. - Apabila terdapat hasil cetak yang rusak atau tidak terbaca, penyedia wajib mengganti tanpa biaya tambahan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2472780);
