INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65970777', 65970777, 'analyze_legacy', 'Badan Pusat Statistik', 'central', 'BADAN PUSAT STATISTIK KAB KUTAI BARAT', 'Perlengkapan Fullday pelatihan petugas', 'Barang', 'Pengadaan Langsung', 'Kalimantan Timur, Kutai Barat (Kab.)', 1350000, 'May 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 27 Set, @Rp 50.000 )', '1. Perlengkapan Fullday pelatihan petugas ( 27 Set, @Rp 50.000 );', 'Nama Paket : Perlengkapan Fullday pelatihan petugas Volume : 27 Set Harga Satuan : @ Rp50.000 ________________________________________ 1. Ruang Lingkup Pekerjaan Penyedia melaksanakan pengadaan dan penyerahan perlengkapan pelatihan untuk petugas guna mendukung kelancaran kegiatan pelatihan. ________________________________________ 2. Spesifikasi Teknis 1 (satu) set perlengkapan pelatihan minimal terdiri atas: - Blocknote/buku catatan (1 buah) - Bolpoin (1 buah) - Map/snelhecter (1 buah) - Cetakan materi pelatihan (hardcopy) - Tanda pengenal (ID card) dan tali lanyard (jika diperlukan) (Komposisi isi set dapat disesuaikan dengan kebutuhan pelatihan.) ________________________________________ 3. Persyaratan Barang - Seluruh barang merupakan barang baru, tidak rusak, dan layak pakai. - Kualitas barang memenuhi standar perlengkapan perkantoran/pelatihan. - Hasil cetakan materi jelas, tidak buram, dan rapi. - Harga yang ditawarkan merupakan harga wajar dan sesuai harga pasar yang berlaku. - Harga sudah termasuk pajak dan biaya pengemasan serta pengiriman. - Penyedia bertanggung jawab atas kelengkapan dan kualitas barang yang diserahkan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2472950);
