INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65969758', 65969758, 'analyze_legacy', 'Badan Pusat Statistik', 'central', 'BADAN PUSAT STATISTIK KAB KUTAI BARAT', 'Penayangan ILM di media cetak, online, sosial, elektronik kab/kota', 'Jasa Lainnya', 'Pengadaan Langsung', 'Kalimantan Timur, Kutai Barat (Kab.)', 2192000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1 Paket, @Rp 2.192.000 )', '1. Penayangan ILM di media cetak, online, sosial, elektronik kab/kota ( 1 Paket, @Rp 2.192.000 );', 'Nama Paket : Penayangan Iklan Layanan Masyarakat (ILM) di Media Cetak, Online, Sosial, dan Elektronik Kab/Kota Volume : 1 (Satu) Paket Harga Satuan : @ Rp2.192.000 1. Ruang Lingkup Pekerjaan Penyedia melaksanakan penayangan Iklan Layanan Masyarakat (ILM) terkait kegiatan/program pada media cetak, media online, media sosial, dan/atau media elektronik tingkat kabupaten/kota sesuai dengan kesepakatan. 2. Spesifikasi Teknis - Materi ILM disediakan oleh pihak penyelenggara atau disesuaikan berdasarkan arahan yang diberikan. - Penayangan dilakukan pada media yang memiliki jangkauan audiens di wilayah kabupaten/kota. - Bentuk penayangan dapat berupa: * Iklan pada media cetak (koran/majalah lokal) * Banner/artikel pada media online * Posting/konten berbayar pada media sosial resmi * Spot siaran pada radio/televisi lokal (jika termasuk dalam paket) - Periode penayangan disesuaikan dengan kesepakatan, dengan bukti tayang (clipping, screenshot, rekaman siaran, atau laporan analytics). 3. Persyaratan - Harga yang ditawarkan merupakan harga wajar dan sesuai harga pasar yang berlaku. - Harga sudah termasuk pajak dan biaya administrasi lainnya. - Penyedia bertanggung jawab atas kesesuaian jadwal dan media penayangan. - Penyedia wajib menyerahkan bukti tayang sebagai dasar pertanggungjawaban. - Apabila penayangan tidak sesuai kesepakatan, penyedia wajib melakukan penayangan ulang tanpa biaya tambahan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2473387);
