INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65969572', 65969572, 'analyze_legacy', 'Badan Pusat Statistik', 'central', 'BADAN PUSAT STATISTIK KAB KUTAI BARAT', 'Paket meeting fullday penyelenggaraan pelatihan petugas survei-survei di neraca produksi', 'Jasa Lainnya', 'Pengadaan Langsung', 'Kalimantan Timur, Kutai Barat (Kab.)', 1530000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 15 OP, @Rp 102.000 )', 'Paket meeting fullday penyelenggaraan pelatihan petugas survei-survei di neraca produksi ( 15 OP, @Rp 102.000 );', 'Nama Paket : Paket Meeting Fullday Penyelenggaraan Pelatihan Petugas Survei-Survei Neraca Produksi Volume : 15 OP (Orang Pelatihan) Harga Satuan : @ Rp102.000 1. Ruang Lingkup Pekerjaan Penyedia melaksanakan penyediaan paket meeting full day untuk peserta pelatihan petugas survei-survei Neraca Produksi, mencakup konsumsi, fasilitas, dan perlengkapan pendukung kegiatan pelatihan. 2. Spesifikasi Teknis - Paket meeting diberikan untuk setiap peserta pelatihan selama 1 (satu) hari penuh/fullday. - Paket meeting minimal mencakup: *Snack pagi (1 porsi) *Makan siang (1 porsi) *Snack sore (1 porsi) *Air mineral (1 botol) - Kualitas konsumsi sesuai standar kebersihan dan kesehatan. - Penyajian dalam kondisi layak saji dan higienis. - Fasilitas pendukung (meja, kursi, proyektor, sambungan listrik, pengeras suara, tisu) disediakan sesuai kebutuhan kegiatan pelatihan. 3. Persyaratan - Harga paket yang ditawarkan sudah termasuk seluruh biaya pajak dan jasa. - Harga merupakan harga wajar dan sesuai harga pasar yang berlaku. - Penyedia bertanggung jawab atas kelengkapan dan kualitas konsumsi serta fasilitas yang disediakan. - Jika terjadi kekurangan atau ketidaksesuaian fasilitas/konsumsi, penyedia wajib melakukan perbaikan atau penggantian tanpa biaya tambahan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2473604);
