INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65969759', 65969759, 'analyze_legacy', 'Badan Pusat Statistik', 'central', 'BADAN PUSAT STATISTIK KAB KUTAI BARAT', 'Penyelenggaraan Pencanangan SE2026 oleh Kepala Daerah (Kabkota)', 'Jasa Lainnya', 'Pengadaan Langsung', 'Kalimantan Timur, Kutai Barat (Kab.)', 5392000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1 Paket, @Rp 5.392.000 )', '1. Penyelenggaraan Pencanangan SE2026 oleh Kepala Daerah (Kabkota) ( 1 Paket, @Rp 5.392.000 );', 'Nama Paket : Penyelenggaraan Pencanangan SE2026 oleh Kepala Daerah (Kab/Kota) Volume : 1 (Satu) Paket Harga Satuan : @ Rp5.392.000 1. Ruang Lingkup Pekerjaan Penyedia melaksanakan penyelenggaraan kegiatan pencanangan SE2026 oleh Kepala Daerah tingkat kabupaten/kota, termasuk penyediaan perlengkapan, fasilitas, dan dukungan teknis kegiatan. 2. Spesifikasi Teknis - Penyediaan perlengkapan acara, meliputi: - Backdrop/spanduk kegiatan - Meja dan kursi tamu undangan - Sound system dan mikrofon - Podium (jika diperlukan) - Dokumentasi kegiatan (foto dan/atau video sederhana) - Penataan tempat kegiatan secara rapi dan representatif. - Pemasangan backdrop/spanduk sesuai desain yang disediakan oleh penyelenggara. - Penyediaan konsumsi ringan dan air mineral bagi tamu undangan (jika termasuk dalam paket). - Dukungan teknis selama acara berlangsung hingga selesai. 3. Persyaratan - Harga yang ditawarkan merupakan harga wajar dan sesuai harga pasar yang berlaku. - Harga sudah termasuk pajak, biaya pengiriman, pemasangan, dan pembongkaran perlengkapan. - Penyedia bertanggung jawab atas kelancaran teknis pelaksanaan kegiatan. - Apabila terjadi kekurangan fasilitas atau gangguan teknis akibat kelalaian penyedia, wajib dilakukan perbaikan tanpa biaya tambahan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2473829);
