INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65969929', 65969929, 'analyze_legacy', 'Badan Pusat Statistik', 'central', 'BADAN PUSAT STATISTIK KAB KUTAI BARAT', 'Asuransi petugas', 'Jasa Lainnya', 'Dikecualikan', 'Kalimantan Timur, Kutai Barat (Kab.)', 135000, 'August 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 7, OB, @ 19.286 )', '1. Asuransi petugas ( 7, OB, @ 19.286 );', 'Nama Paket : Asuransi Petugas Volume : 7 OB (Orang Bulan) Harga Satuan : @ Rp19.286 1. Ruang Lingkup Pekerjaan Penyedia melaksanakan penyediaan layanan asuransi bagi petugas kegiatan selama masa penugasan, guna memberikan perlindungan terhadap risiko kecelakaan kerja dan/atau risiko lainnya sesuai ketentuan polis. 2. Spesifikasi Teknis Asuransi diberikan kepada petugas yang tercantum dalam daftar nominatif. Masa pertanggungan sesuai periode penugasan (1 OB per orang per bulan). Jenis perlindungan minimal mencakup: Santunan meninggal dunia akibat kecelakaan. Santunan cacat tetap akibat kecelakaan. Biaya perawatan/pengobatan akibat kecelakaan (sesuai ketentuan polis). Polis asuransi diterbitkan secara resmi dan sah sesuai peraturan perasuransian yang berlaku. 3. Persyaratan Harga premi merupakan harga wajar dan sesuai ketentuan yang berlaku. Harga sudah termasuk seluruh pajak dan biaya administrasi. Penyedia merupakan perusahaan asuransi yang memiliki izin usaha resmi. Penyedia wajib menyerahkan bukti kepesertaan/polis sebagai dasar pertanggungjawaban. Proses klaim harus jelas dan dapat dilakukan sesuai prosedur yang ditetapkan dalam polis.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2473892);
