INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66010330', 66010330, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Staf Back End Developer, Kegiatan Hibah Global Environment Facility (GEF) Indonesia  Sustainable City Impact Project, Direktorat Perumahan dan Infrastruktur Kawasan Permukiman (PIKP)', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 108000000, 'December 2025', 'APBN - HIBAH LUAR NEGERI (I)', 0, 1, '9', 'Untuk mendukung kegiatan Direktorat PIKP sebagai Koordinator PIU Komponen 2 GEF-SCIP, khususnya yang terkait pengembangan sistem informasi; Merancang, mengembangkan, dan mengelola server, basis data (database), dan logika aplikasi (application logic) utuk sistem/platform digital yang diperlukan Direktorat PIKP dalam lingkup GEF SCIP berdasarkan bisnis proses yang disepakati; Membuat API (Application Programming Interface) untuk integrasi data dengan sistem eksternal (jika diperlukan); Memastikan sistem/platform digital yang dikembangkan dapat diakses dengan optimal di berbagai perangkat dan browser, serta mempertimbangkan aspek keamanan dalam implementasi dan melakukan uji fungsi dan uji keandalan sistem terutama pada bagian back-end; Menyusun buku manual penggunaan sistem/platform serta menyusun dokumen SDLC yang termuat dalam laporan progres bulanan.', 'Pendidikan minimal S1, diutamakan dari jurusan ilmu komputer, teknik informatika atau jurusan teknik lainnya. Memiliki pengalaman kerja profesional minimal 3 (tiga) tahun yang berkaitan dengan pengembangan sistem informasi. Memiliki pengalaman dan pengetahuan dalam pengembangan sistem informasi berbasis web dengan menggunakan manajemen basis data relasional berupa PostgreSQL. Disertai dengan kemampuan pemrosesan data spasial menggunakan PostGIS atau sejenisnya, kemampuan dalam mengelola API yang konsisten dan terdokumentasikan dengan baik. Hal tersebut dibuktikan dengan menyampaikan portofolio yang menampilkan proyek dengan fungsi management API dan/atau dokumentasi SDLC terutama Entity Relationship Diagram (ERD) proyek yang pernah dikerjakan sebelumnya. Mampu bekerja dalam tim dan bersedia ditugaskan ke berbagai lokasi untuk kepentingan pekerjaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2475005);
