INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65970141', 65970141, 'analyze_legacy', 'Badan Pusat Statistik', 'central', 'BADAN PUSAT STATISTIK KAB KUTAI BARAT', 'pencetakan buku pedoman pencacah vimk26 tahunan', 'Barang', 'Pengadaan Langsung', 'Kalimantan Timur, Kutai Barat (Kab.)', 529000, 'July 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1059 Lmbr, @Rp 500 )', '1. pencetakan buku pedoman pencacah vimk26 tahunan ( 1059 Lmbr, @Rp 500 );', 'Nama Paket : Pencetakan Buku Pedoman Pencacah VIMK26 Tahunan Volume : 1.059 (Seribu Lima Puluh Sembilan) Lembar Harga Satuan : @ Rp500 1. Ruang Lingkup Pekerjaan Penyedia melaksanakan pencetakan Buku Pedoman Pencacah VIMK26 Tahunan sesuai dengan naskah dan desain yang disediakan oleh penyelenggara. 2. Spesifikasi Teknis - Pencetakan dilakukan sesuai format, tata letak, dan isi naskah tanpa perubahan. - Menggunakan kertas HVS ukuran A4/F4 dengan gramasi standar 70/75 gsm. - Hasil cetakan jelas, tajam, tidak buram, dan tidak terpotong. - Tinta tidak mudah luntur dan tidak tembus berlebihan ke halaman belakang. - Dicetak bolak-balik atau satu sisi sesuai desain yang ditetapkan. - Dokumen disusun rapi dan dijilid sederhana (steples/lakban panas/spiral sederhana sesuai kebutuhan). 3. Persyaratan - Harga yang ditawarkan merupakan harga wajar dan sesuai harga pasar yang berlaku. - Harga sudah termasuk pajak, biaya pencetakan, dan penjilidan. - Penyedia bertanggung jawab atas kualitas hasil cetak, penjilidan, dan ketepatan jumlah lembar. - Apabila terdapat hasil cetak yang rusak atau tidak sesuai spesifikasi, penyedia wajib melakukan penggantian tanpa biaya tambahan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2475084);
