INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66011371', 66011371, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Developing Sustainable Urban Mobility Plan (SUMP) for Palembang', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 9500000000, 'February 2026', 'APBN - HIBAH LUAR NEGERI (I)', 0, 1, '12', 'RUANG LINGKUP: The objective of the consultant is to support the Government of Indonesia and the City of Palembang in formulating a policy-oriented, implementable, and measurable Sustainable Urban Mobility Plan (SUMP), in accordance with the Terms of Reference (ToR) for the SUMP Palembang assignment and the World Bank Environmental and Social Framework (ESF). The appointed consultant will undertake: b. Comprehensive stocktaking and diagnostic analysis of current urban spatial and mobility conditions; c. Extensive consultations with the general public, relevant local government agencies, and technical ministries to identify development needs, long-term vision, spatial growth scenarios, urban mobility trends, and strategies to address identified barriers; d. Accessibility and service equity analysis through the use of appropriate transport modeling and survey tools.', 'SPESIFIKASI: b. Relevant experience of the firm in the last 10 years in the following key areas in Indonesia: a. Urban Mobility & Transport Policy b. Environmental & Social Safeguards c. Climate Change & Biodiversity d. Urban Logistics', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2475615);
