INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65969757', 65969757, 'analyze_legacy', 'Badan Pusat Statistik', 'central', 'BADAN PUSAT STATISTIK KAB KUTAI BARAT', 'baliho dan pemasangan bahan sosialisasi pelaksanaan SE2026', 'Barang', 'Pengadaan Langsung', 'Kalimantan Timur, Kutai Barat (Kab.)', 3200000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 20 Buah, @Rp 160.000 )', '1. baliho dan pemasangan bahan sosialisasi pelaksanaan SE2026 ( 20 Buah, @Rp 160.000 );', 'Nama Paket : Baliho dan Pemasangan Bahan Sosialisasi Pelaksanaan SE2026 Volume : 20 (Dua Puluh) Buah Harga Satuan : @ Rp160.000 1. Ruang Lingkup Pekerjaan Penyedia melaksanakan pencetakan dan pemasangan baliho sebagai media sosialisasi pelaksanaan SE2026 pada lokasi yang telah ditentukan. 2. Spesifikasi Teknis - Baliho dicetak menggunakan bahan flexi/banner dengan kualitas standar luar ruang (outdoor). - Ukuran baliho disesuaikan dengan kebutuhan (misalnya ± 2 x 3 meter atau sesuai spesifikasi yang ditetapkan). - Cetakan menggunakan tinta outdoor yang tahan terhadap cuaca (panas dan hujan). - Desain materi sosialisasi disediakan oleh pihak penyelenggara. - Pemasangan dilakukan pada titik/lokasi yang telah ditentukan, termasuk rangka sederhana atau pengikatan yang aman dan rapi. - Hasil pemasangan harus kuat, tidak mudah lepas, dan mudah terbaca oleh masyarakat. 3. Persyaratan - Harga yang ditawarkan merupakan harga wajar dan sesuai harga pasar yang berlaku. - Harga sudah termasuk biaya desain (jika diperlukan), cetak, pengiriman, dan pemasangan. - Penyedia bertanggung jawab atas kualitas cetakan dan kerapian pemasangan. - Apabila terjadi kerusakan akibat kualitas bahan atau pemasangan yang tidak sesuai standar, penyedia wajib melakukan perbaikan tanpa biaya tambahan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2476261);
