INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65970067', 65970067, 'analyze_legacy', 'Badan Pusat Statistik', 'central', 'BADAN PUSAT STATISTIK KAB KUTAI BARAT', 'Pencetakan Kuesioner Survei Harga Produsen 2027', 'Barang', 'Pengadaan Langsung', 'Kalimantan Timur, Kutai Barat (Kab.)', 3009000, 'November 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 6019 Lmbr, @Rp 500 )', '1. Pencetakan Kuesioner Survei Harga Produsen 2027 ( 6019 Lmbr, @Rp 500 );', 'Nama Paket : Pencetakan Kuesioner Survei Harga Produsen 2027 Volume : 6.019 (Enam Ribu Sembilan Belas) Lembar Harga Satuan : @ Rp500 1. Ruang Lingkup Pekerjaan Penyedia melaksanakan pencetakan kuesioner Survei Harga Produsen Tahun 2027 sesuai dengan format dan naskah yang disediakan oleh penyelenggara. 2. Spesifikasi Teknis - Pencetakan dilakukan sesuai desain, format, dan tata letak asli tanpa perubahan isi. - Menggunakan kertas HVS ukuran A4/F4 dengan gramasi standar 70/75 gsm. - Hasil cetakan jelas, tajam, tidak buram, dan tidak terpotong. - Tinta cetak tidak mudah luntur dan tidak tembus berlebihan ke halaman belakang. - Kuesioner dicetak bolak-balik atau satu sisi sesuai kebutuhan desain. - Dokumen disusun dan dikemas rapi sesuai jumlah yang ditentukan. 3. Persyaratan - Harga yang ditawarkan merupakan harga wajar dan sesuai harga pasar yang berlaku. - Harga sudah termasuk pajak dan biaya pengemasan. - Penyedia bertanggung jawab atas kualitas hasil cetak dan ketepatan jumlah lembar. - Apabila terdapat hasil cetak yang rusak, tidak terbaca, atau tidak sesuai spesifikasi, penyedia wajib melakukan penggantian tanpa biaya tambahan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2476269);
