INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66009782', 66009782, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Tenaga Ahli Sistem Analis, Kegiatan Hibah Sustainable City Impact Program, Direktorat Perumahan dan Kawasan Permukiman', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 275000000, 'December 2025', 'APBN - HIBAH LUAR NEGERI (I)', 0, 1, '11', '1. Mendampingi dan melakukan supervisi terhadap paket kegiatan konsultan firma dalam hal substansi pengembangan aplikasi berbasis web dalam rangka meningkatkan tata kelola di bidang air minum, sanitasi, dan limbah, yang mendukung kegiatan GEF-SCIP; 2. Menyusun laporan khusus terkait analisis sistem pertukaran data antar aplikasi di sektor air minum, sanitasi, dan persampahan; 3. Menyusun definisi dan kebutuhan pengembangan aplikasi untuk mengelola data dalam rangka mendukung fungsi Direktorat Perumahan dan Infrastruktur Kawasan Permukiman, khususnya di bidang air minum, sanitasi, dan persampahan; 4. Menyusun kebutuhan aplikasi berbasis web internal di lingkungan Direktorat Perumahan dan Infrastruktur Kawasan Permukiman untuk mendukung program hibah GEF Indonesia SCIP;', 'Pendidikan minimal S1 dari jurusan Teknik Informatika, Teknik Komputer, Teknologi Informasi, atau Ilmu Komputer. Memiliki pengalaman kerja profesional minimal 5 (lima) tahun yang berkaitan dengan pemrograman perangkat lunak, pemrograman basis data dan/atau sebagai analis sistem. Dibuktikan dengan portofolio aplikasi berbasis web, minimal 3 aplikasi berbasis web. Diutamakan yang memiliki sertifikasi di bidang system analis seperti MCITP (Microsoft Certified IT Professional) atau sertifikasi yang setara. Mampu menganalisa kebutuhan pengguna, bisnis, dan fungsional dari sistem yang akan dikembangkan. Dapat bekerja dalam tim dan bersedia ditugaskan ke berbagai lokasi untuk keperluan pekerjaan. Memiliki inisiatif yang tinggi dan dapat bekerja secara mandiri maupun bekerja sama dalam tim.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2476323);
