INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65970070', 65970070, 'analyze_legacy', 'Badan Pusat Statistik', 'central', 'BADAN PUSAT STATISTIK KAB KUTAI BARAT', 'pengadaan komputer supplies kabupaten/kota', 'Barang', 'Pengadaan Langsung', 'Kalimantan Timur, Kutai Barat (Kab.)', 1875000, 'August 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 4, Paket, @Rp 468.750 )', '1. pengadaan komputer supplies kabupaten/kota ( 4 Paket, @Rp 468.750 );', 'Nama Paket : pengadaan komputer supplies kabupaten/kota Volume : 4 Paket Harga Satuan : @ Rp468.750 1. Ruang Lingkup Pekerjaan Penyedia melaksanakan pengadaan dan penyerahan perlengkapan komputer (computer supplies) guna mendukung kegiatan operasional perkantoran di tingkat kabupaten/kota. 2. Spesifikasi Teknis 1 paket komputer supplies minimal dapat terdiri atas: - Tinta printer/toner (sesuai tipe printer yang digunakan) - Flashdisk (minimal 16 GB) - Mouse kabel/wireless (1 unit) - Kabel data/HDMI/VGA (sesuai kebutuhan) - CD/DVD blank atau media penyimpanan lainnya (jika diperlukan) (Komposisi isi paket dapat disesuaikan dengan kebutuhan dan ketersediaan anggaran.) 3. Persyaratan Barang - Seluruh barang merupakan barang baru, bukan rekondisi, dan dalam kondisi baik serta layak pakai. - Spesifikasi barang kompatibel dengan perangkat yang digunakan di kantor kabupaten/kota. - Harga yang ditawarkan merupakan harga wajar dan sesuai harga pasar yang berlaku. - Harga sudah termasuk pajak dan biaya pengiriman ke lokasi tujuan. - Penyedia bertanggung jawab atas kelengkapan, kesesuaian spesifikasi, dan kualitas barang yang diserahkan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2476917);
