INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66011808', 66011808, 'analyze_legacy', 'Kementerian  Kehutanan', 'central', '000002 FOLU NET SINK 2030 RBC2', 'Pengadaan Tenaga Ahli Individu Profesional Non-ASN Bidang Sistem Informasi Geografis (GIS) untuk Penguatan Basisdata Spasial Sektor FOLU', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 100000000, 'March 2026', 'Lainnya', 1, 1, '1 Orang', '1. Melaksanakan pengolahan data geospasial sektor FOLU yang bersumber dari Produsen Data Geospasial di lingkungan Kementerian Kehutanan maupun sumber data pendukung lainnya. 2. Melakukan kompilasi dan integrasi data geospasial multi-sumber untuk mendukung penyusunan basisdata spasial sektor FOLU yang konsisten dan terstandar. 3. Melaksanakan analisis spasial tematik untuk mendukung perencanaan, pemantauan, dan evaluasi pelaksanaan aksi mitigasi Indonesia’s FOLU Net Sink 2030. 4. Mendukung penerapan Quality Assurance (QA) terhadap data dan hasil analisis geospasial sesuai dengan standar Informasi Geospasial Tematik (IGT) yang berlaku. 5. Menyusun dan menyajikan output analisis geospasial dalam bentuk peta tematik, layer spasial, tabel analisis, dan/atau visualisasi data sesuai kebutuhan Direktorat IPSDH. 6. Memberikan dukungan teknis dalam pemanfaatan dan pengelolaan sistem serta platform geospasial yang digunakan oleh Direktorat IPSDH, termasuk portal dan basisdata IGT. 7. Mendukung proses dokumentasi teknis, metadata, dan pelaporan hasil pengolahan serta analisis data geospasial sektor FOLU. 8. Berkoordinasi dengan unit kerja terkait, Produsen Data Geospasial dan BPKH dalam rangka memastikan keterpaduan data, kelancaran alur kerja, serta peningkatan kualitas basisdata spasial sektor FOLU. 9. Melaksanakan tugas pimpinan guna mendukung tugas dan fungsi Direktorat IPSDH.', '● Menguasai perangkat lunak GIS dan pengolahan data spasial, baik berbasis desktop maupun server/web GIS, serta berpengalaman dalam pengelolaan basisdata geospasial. ● Memiliki pengalaman dalam pengolahan dan pemutakhiran data geospasial tematik, termasuk penerapan Quality Assurance dan (QA) sesuai standar Informasi Geospasial Tematik (IGT). ● Memahami kebijakan dan tata kelola Informasi Geospasial, termasuk Kebijakan Satu Peta, Jaringan Informasi Geospasial Nasional (JIGN), serta peran Walidata dan Produsen Data Geospasial. ● Memiliki kemampuan analisis spasial yang baik serta mampu mendukung penyusunan peta tematik dan informasi spasial untuk kebutuhan perencanaan, pemantauan, dan evaluasi, khususnya pada sektor Forestry and Other Land Use (FOLU). ● Mampu bekerja secara mandiri maupun dalam tim, memiliki kemampuan koordinasi dan komunikasi yang baik, serta mampu menyusun laporan teknis secara sistematis dan tepat waktu', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2477707);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65970792', 65970792, 'analyze_legacy', 'Kab. Barito Utara', 'kabkota', 'Badan Pengelolaan Keuangan Dan Aset', 'Belanja Alat/Bahan untuk Kegiatan Kantor- Kertas dan Cover (Sekretariat)', 'Barang', 'E-Purchasing', 'Kalimantan Tengah, Barito Utara (Kab.)', 750000, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Kertas HVS;', 'A4 80Gsm;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2477708);
