INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66010402', 66010402, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Tenaga Ahli Manajemen Kontrak, Kegiatan Hibah Global Environment Facility (GEF) Indonesia  Sustainable City Impact Project, Direktorat Perumahan dan Infrastruktur Kawasan Permukiman (PIKP)', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 240000000, 'December 2025', 'APBN - HIBAH LUAR NEGERI (I)', 0, 1, '12', 'Untuk mendukung kegiatan Sekretaris Deputi Infrastruktur selaku PPK program PPN VIII khususnya yang terkait aspek manajemen kontrak; Melakukan pengawasan administrasi kontrak terhadap kegiatan konsultan firma di Komponen 2 GEF-SCIP; Menyusun laporan pengawasan administrasi kontrak terkait kegiatan dalam komponen 2 GEF SCIP dan melaporkan secara berkala; Menindaklanjuti perbaikan pelaksanaan administrasi kontrak berdasarkan rekomendasi dari Misi Bank Dunia (sesuai dengan komponen kegiatan yang relevan); Memastikan seluruh dokumen pertanggungjawaban memenuhi persyaratan pemerintah dan donor serta memfasilitasi klasifikasi dan analisis informasi keuangan untuk memantau kemajuan proyek. Tugas ini juga mencakup: menghasilkan catatan transaksi keuangan untuk penerimaan, faktur, pembayaran, pengeluaran, pendapatan, dll sebagai dokumentasi transaksi keuangan yang akurat;', 'Pendidikan minimal S1 dari jurusan teknik, manajemen, sosial, ekonomi, atau komunikasi. Memiliki pengalaman kerja profesional minimal 10 (sepuluh) tahun yang berkaitan dengan pengadaan dan pengendalian kontrak proyek-proyek pemerintah dan/atau yang didanai oleh pinjaman dan hibah luar negeri. Memiliki pengalaman dan pengetahuan dalam Environmental and Social Management Framework dan penerapan Environmental and Social Standard dalam proyek. Menguasai dan terampil mengoperasikan komputer, minimal Microsoft Office (Word, Excel, PowerPoint). Memiliki pengalaman dalam proses audit pengelolaan proyek pinjaman dan hibah. Mampu bekerja dalam tim dan bersedia ditugaskan ke berbagai lokasi untuk kepentingan pekerjaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2477710);
