INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66010250', 66010250, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Staf Front End Developer, Kegiatan Hibah Global Environment Facility (GEF) Indonesia  Sustainable City Impact Project, Direktorat Perumahan dan Infrastruktur Kawasan Permukiman (PIKP)', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 108000000, 'December 2025', 'APBN - HIBAH LUAR NEGERI (I)', 0, 1, '9', 'Untuk mendukung kegiatan Direktorat Perumahan dan Infrastruktur Kawasan Permukiman sebagai Koordinator PIU Komponen 2 GEF-SCIP, khususnya yang terkait pengembangan sistem informasi; Mengembangkan antarmuka pengguna (user interface/UI) yang responsif, interaktif dan user-friendly untuk sistem yang diperlukan Direktorat Perumahan dan Infrastruktur Kawasan Permukiman dalam lingkup GEF Indonesia SCIP berdasarkan desain yang disepakati; Memastikan sistem/platform digital yang dikembangkan dapat diakses dengan optimal di berbagai perangkat dan browser, serta mempertimbangkan aspek keamanan dalam implementasi dan melakukan uji fungsi dan uji keandalan sistem terutama pada bagian front-end; Menyusun buku manual penggunaan sistem/platform serta menyusun dokumen SDLC yang termuat dalam laporan progres bulanan.', 'Pendidikan minimal S1, diutamakan dari jurusan ilmu komputer, teknik informatika atau jurusan teknik lainnya. Memiliki pengalaman kerja profesional minimal 3 (tiga) tahun yang berkaitan dengan pengembangan sistem informasi. Memiliki pengalaman dan pengetahuan dalam pengembangan sistem informasi berbasis web dengan menggunakan salah satu dari framework seperti React.js, Vue.js, atau Angular. Disertai dengan kemampuan visualisasi data dan peta digital. Hal tersebut dibuktikan dengan menyampaikan portofolio yang menampilkan proyek dengan fungsi dashboard peta interaktif atau visualisasi data kompleks. Mampu bekerja dalam tim dan bersedia ditugaskan ke berbagai lokasi untuk kepentingan pekerjaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2477887);
