INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65971515', 65971515, 'analyze_legacy', 'Badan Pusat Statistik', 'central', 'BADAN PUSAT STATISTIK KAB KUTAI BARAT', 'biaya paket data pengumpulan data updating direktori perusahaan pertanian (dpp) dan direktori usaha pertanian lainnya (dutl)', 'Barang', 'Pengadaan Langsung', 'Kalimantan Timur, Kutai Barat (Kab.)', 200000, 'June 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 4 OB, @Rp 50.000 )', '1. biaya paket data pengumpulan data updating direktori perusahaan pertanian (dpp) dan direktori usaha pertanian lainnya (dutl) ( 4 OB, @Rp 50.000 );', 'Nama Paket : biaya paket data pengumpulan data updating direktori perusahaan pertanian (dpp) dan direktori usaha pertanian lainnya (dutl) Volume : 4 OB (Orang Bulan) Harga Satuan : @ Rp50.000 1. Ruang Lingkup Pekerjaan Penyedia melaksanakan pengadaan dan penyaluran paket data internet/pulsa seluler untuk mendukung kegiatan pencacahan di wilayah Kabupaten Kutai Barat 2. Spesifikasi Teknis - Paket data/pulsa diberikan kepada nomor petugas pencacahan aktif. - Nilai paket data/pulsa sebesar Rp50.000 per OB. - Paket data dapat digunakan untuk akses internet dan/atau komunikasi seluler guna mendukung pelaksanaan pencacahan. - Masa aktif paket/pulsa minimal 30 (tiga puluh) hari sejak aktivasi. - Jaringan provider memiliki cakupan layanan yang memadai di wilayah domisili petugas. 3. Persyaratan - Paket data/pulsa dalam kondisi aktif dan siap digunakan. - Harga yang ditawarkan merupakan harga wajar dan sesuai harga pasar yang berlaku. - Harga sudah termasuk pajak dan biaya administrasi lainnya. - Penyedia bertanggung jawab atas keberhasilan pengisian/aktivasi paket data kepada nomor tujuan. - Apabila terjadi kegagalan pengisian, penyedia wajib melakukan penggantian tanpa biaya tambahan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2478298);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66010940', 66010940, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'The Preparation Of Infrastructure Governance, Feasibility Study, And Environmental & Social Impact Assessment Documents For Coastal Zone Corridor In Semarang City', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 9500000000, 'February 2026', 'APBN - HIBAH LANGSUNG LUAR NEGERI (K), APBN - HIBAH LUAR NEGERI (I)', 0, 1, '12', 'RUANG LINGKUP: The objective of the consultant is to prepare the technical and environmental-social documents that refer to provided feasibility study preparation guideline. Some of the things that need to be prepared include but not limited to: a. Preparation of Infrastructure Governance Assessment to make sure the viability of sub-projects facilitated in Bitung City. b. Preparation of Feasibilities Studies and Environmental and Social Impact Assessment complemented with biodiversity assessment of Sustainable Water Distribution for Semarang Waterfront to support the fulfilment of readiness criteria for selected sub-projects in the GEF Indonesia SCIP program and in accordance with feasibility study preparation guideline.', 'SPESIFIKASI: a. Experience in preparation or development of Feasibility Study (FS) of integrated area development or multi-sector infrastructure project for the last ten years. b. Experience in preparation or development of Environmental & Social Impact Assessment (ESIA) of integrated area development or multi-sector infrastructure project for the last ten years. c. Experience working in the field of consulting services on topics related to sustainable city infrastructure, nature-based solutions, climate change, and/or biodiversity (experience in water supply, wastewater management, and/or sustainable landscapes is an advantage). d. Experience in Indonesia and/or comparable urban contexts (Bitung experience is an advantage).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2478299);
