INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66010840', 66010840, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Pengadaan Tenaga Ahli Desain Informasi dan Visualisasi Data Kegiatan Penyusunan Dokumen Teknis Kota Balikpapan dan Kota Palembang dalam rangka Global Environment Facility Sustainable Cities Impact Project (GEF-SCIP) di Lingkungan Kerja Direktorat Konektivitas dan Infrastruktur Logistik, Kedeputian Bidang Infrastruktur', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 96000000, 'December 2025', 'APBN - HIBAH LUAR NEGERI (I)', 0, 1, '12', '1. Mendukung tim proyek dalam penyusunan materi visual, infografis, dan presentasi yang berkaitan dengan perencanaan, pelaksanaan, dan pelaporan proyek, termasuk visualisasi konsep BRT, alur kerja proyek, jadwal kegiatan, dan capaian program. 2. Mengolah data teknis, kebijakan, dan administratif proyek menjadi materi visual yang komunikatif, informatif, dan mudah dipahami untuk kebutuhan nternal Bappenas, PMU, donor, serta pemangku kepentingan terkait. 3. Menyusun desain infografis untuk laporan proyek (Preliminary Report, Progress Report, Monitoring & Evaluation Report, dan laporan lainnya) sesuai dengan pedoman visual dan standar komunikasi PMU dan donor. 4. Mendukung penyusunan materi presentasi (slide deck) untuk rapat koordinasi, workshop, FGD, dan forum komunikasi dengan donor, pemerintah daerah, serta konsultan.', 'a. Pendidikan perguruan tinggi minimal S-1 bidang Desain Komunikasi Visual, Desain Grafis, Multimedia, Komunikasi, atau bidang lain yang relevan; b. Memiliki pengalaman kerja sebagai staf visualisasi data, desainer grafis, atau bidang terkait minimal 1 tahun, khususnya dalam proyek pemerintah, donor, atau lembaga nasional/internasional (melampirkan bukti referensi/kontrak kerja/portofolio); c. Mampu mengolah data dan informasi teknis menjadi infografis dan materi visual yang jelas dan komunikatif; d. Menguasai perangkat lunak desain grafis dan presentasi (misalnya Figma, Adobe Illustrator, Adobe InDesign, Adobe Photoshop, Canva, PowerPoint, atau perangkat sejenis); e. Memiliki portofolio infografis, visualisasi data, atau materi presentasi yang relevan; f. Memiliki kemampuan komunikasi yang baik serta mampu bekerja sama dengan tim teknis dan administrasi', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2478412);
