INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66010482', 66010482, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Institutional and Governance Specialist, Kegiatan Hibah Global Environment Facility (GEF) Indonesia  Sustainable City Impact Project, Direktorat Perumahan dan Infrastruktur Kawasan Permukiman (PIKP)', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 300000000, 'December 2025', 'APBN - HIBAH LUAR NEGERI (I)', 0, 1, '12', 'Melakukan perencanaan, pemantauan, dan pelaporan proyek GEF SCIP di lingkungan PIU Direktorat Perumahan dan Infrastruktur Kawasan Permukiman khususnya pada aspek kelembagaan dan tata kelola; Melakukan koordinasi dan penguatan hubungan kelembagaan dengan pemangku kepentingan GEF SCIP Komponen 2;; Melakukan supervisi terhadap konsultan firma di komponen 2 GEF SCIP; Melakukan pengelolaan risiko proyek di lingkungan PIU Direktorat Perumahan dan Infrastruktur Kawasan Permukiman dan Komponen 2 GEF SCIP', 'Pendidikan minimal S1 dari jurusan sosial, politik, manajemen, ekonomi, atau manajemen bisnis. Memiliki pengalaman kerja profesional minimal 8 (delapan) tahun yang berkaitan dengan pengelolaan proyek-proyek pemerintah dan/atau yang didanai oleh pinjaman dan hibah luar negeri dengan tugas terkait aspek kelembagaan pada sektor pengelolaan sampah, air limbah domestik, dan air minum. Memiliki pengalaman di bidang fasilitasi kelembagaan dan/atau pendampingan penyusunan produk perencanaan pembangunan skala daerah maupun nasional.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2478510);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66012588', 66012588, 'analyze_legacy', 'Kementerian Pemberdayaan Perempuan Dan Perlindungan Anak', 'central', 'DEPUTI BIDANG PEMENUHAN HAK ANAK', '6373.UAE.001.051.B - PAKET MEETING FULLBOARD', 'Jasa Lainnya', 'Dikecualikan', 'Jawa Barat, Bogor (Kota)', 10500000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '( 15, OP, @ 700000 )', '1. PAKET MEETING FULLBOARD ( 15, OP, @ 700000 );', '1. PAKET MEETING FULLBOARD ( 15, OP, @ 700000 );', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2478511);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65970452', 65970452, 'analyze_legacy', 'Badan Pusat Statistik', 'central', 'BADAN PUSAT STATISTIK KAB KUTAI BARAT', 'pelatihan petugas Survei Angkatan Kerja Nasional agustus', 'Jasa Lainnya', 'Pengadaan Langsung', 'Kalimantan Timur, Kutai Barat (Kab.)', 4500000, 'July 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 15 OP, @Rp 300.000 )', '1. pelatihan petugas Survei Angkatan Kerja Nasional agustus ( 15 OP, @Rp 300.000 );', 'Nama Paket : pelatihan petugas Survei Angkatan Kerja Nasional agustus Volume : 15 OP (Orang Pelatihan) Harga Satuan : @ Rp 300.000 ________________________________________ 1. Ruang Lingkup Pekerjaan Penyedia melaksanakan penyediaan paket meeting full day untuk peserta pelatihan petugas, mencakup konsumsi, fasilitas, dan perlengkapan pendukung kegiatan pelatihan. ________________________________________ 2. Spesifikasi Teknis 1. Paket meeting diberikan untuk setiap peserta pelatihan selama 1 (satu) hari penuh. 2. Paket meeting minimal mencakup: - Snack pagi (1 porsi) - Makan siang (1 porsi) - Snack sore (1 porsi) - Air mineral (1 botol) 3. Kualitas konsumsi sesuai standar kebersihan dan kesehatan. 4. Penyajian dalam kondisi layak saji dan higienis. 5. Fasilitas pendukung (meja, kursi, alat tulis, serbet, dan perlengkapan makan) disediakan sesuai kebutuhan kegiatan pelatihan. ________________________________________ 3. Persyaratan 1. Harga paket yang ditawarkan sudah termasuk seluruh pajak, biaya pengemasan, dan penyajian. 2. Harga merupakan harga wajar dan sesuai harga pasar yang berlaku. 3. Penyedia bertanggung jawab atas kelengkapan dan kualitas konsumsi serta fasilitas yang disediakan. 4. Jika terjadi kekurangan atau ketidaksesuaian fasilitas/konsumsi, penyedia wajib melakukan perbaikan atau penggantian tanpa biaya tambahan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2478512);
