INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66010629', 66010629, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Pengadaan Tenaga Ahli Manajemen Implementasi Proyek Kegiatan Penyusunan Dokumen Teknis Kota Balikpapan dan Kota Palembang dalam rangka Global Environment Facility Sustainable Cities Impact Project (GEF-SCIP) di Lingkungan Kerja Direktorat Konektivitas dan Infrastruktur Logistik, Kedeputian Bidang Infrastruktur', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 96000000, 'December 2025', 'APBN - HIBAH DALAM NEGERI (H)', 0, 1, '12', '1. mendukung tim proyek dalam penyusunan Rencana Kerja Tahunan (Annual Work Plan) dan memastikan seluruh kegiatan proyek terdokumentasi dengan baik, termasuk penyusunan Rencana Pengadaan (Procurement Plan) dan pengunggahan dokumen ToR, RFP, serta paket pengadaan ke dalam sistem STEP (Systematic Tracking of Exchanges in Procurement) sesuai panduan dari PMU dan donor. 2. mengkoordinasikan jadwal dan pelaksanaan kegiatan proyek agar sesuai dengan rencana kerja, termasuk penyiapan dokumen administrasi pendukung seperti notulen rapat, surat-menyurat resmi, dan laporan kemajuan kegiatan. 3. mendukung proses administrasi penganggaran dan keuangan proyek dengan memastikan kesesuaian antara Rencana Kerja, DIPA, dan rencana pembelanjaan proyek, serta membantu tim proyek dalam proses revisi DIPA dan budget reallocation bila diperlukan.', 'a. Pendidikan perguruan tinggi negeri minimal S-1 bidang Administrasi, Manajemen, Ekonomi, Akuntansi, Sekretari, atau bidang lain yang relevan; b. Memiliki pengalaman kerja bidang administrasi proyek pemerintah, donor, atau lembaga nasional ataupun internasional minimal 1 tahun; c. Memiliki pengalaman bekerja dalam sektor pemerintahan minimal 1 tahun (melampirkan bukti referensi/kontrak kerja/bukti contoh hasil tulisan) d. Mampu menggunakan sistem STEP (Systematic Tracking of Exchanges in Procurement) untuk unggah ToR, RFP, evaluasi, dan laporan pengadaan; e. Memiliki pengalaman dalam mengikuti workshop, training atau sejenis (melampirkan bukti referensi/sertifikat); f. Memiliki pengalaman organisasi yang memadai; g. Memiliki kemampuan menulis laporan serta membuat presentasi (melampirkan bukti referensi/kontrak kerja/bukti contoh hasil tulisan)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2479524);
